        all_records = records(
            ("r0", "ACGT"), ("r1", "GGGG"), ("r2", "TTAA"), ("r3", "ACGNAC")
        )

        def as_pairs(index: KmerIndex):
            return [
                (kmer, [(o.record, o.id, o.position, o.strand) for o in occurrences])
                for kmer, occurrences in index.items()
            ]

